func PullModel(ctx, name, regOpts, fn) error {
  existingMf, err := manifest.ParseNamedManifest(n) // build deleteMap of old layers
  mf, manifestData, err := pullModelManifest(ctx, n, regOpts)
  for _, layer := range layers { downloadBlob(ctx, downloadOpts{n, layer.Digest, regOpts, fn}) }
  for _, layer := range layers { if err := verifyBlob(layer.Digest); err != nil {...} }
  fp, err := manifest.PathForName(n)
  err = os.WriteFile(fp, manifestData, 0o644)
  if !envconfig.NoPrune() && len(deleteMap) > 0 { deleteUnusedLayers(deleteMap) }
}

func PushModel(ctx, name, regOpts, fn) error {
  if n.ProtocolScheme == "http" && !regOpts.Insecure { return errInsecureProtocol }
  mf, err := manifest.ParseNamedManifest(n)
  for _, layer := range append(mf.Layers, mf.Config) { uploadBlob(ctx, n, layer, regOpts, fn) }
  err = uploadManifest(ctx, n, regOpts, fn, mf) // HTTP PUT to registry
}

