func CopyModel(src, dst model.Name) error {
  if src.Filepath() == dst.Filepath() { return nil }
  dstpath := filepath.Join(manifests, dst.Filepath()); os.MkdirAll(filepath.Dir(dstpath), 0o755)
  srcfile, _ := os.Open(srcpath); dstfile, _ := os.Create(dstpath)
  _, err = io.Copy(dstfile, srcfile)
}

